def parse_options(m: Match[str]) -> List[Tuple[str, str]]:
    text = m.group('options')
    if not text.strip():
        return []

    options = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        if ':' in line:
            i = line.find(':')
            k = line[:i].strip()
            v = line[i + 1:].strip()
            options.append((k, v))
    return options
